TUTORIALS = []

TUTORIALS.append({'title': 'FS-1. Setup: folders, INSTALLED_APPS, urls, how to add a report', 'category': 'programming', 'order': 1, 'summary': 'Do this first: the app layout, settings, and how a .sql file becomes a page.', 'content': '<p>Step 1 of 11. Create the app folder with this layout. <code>__init__.py</code> is empty. Add <code>"fast_search"</code> to <code>INSTALLED_APPS</code> and include its urls. There are no models, so no migrations, and nothing is ever saved.</p>\n<p>Needs <code>oracledb</code>, <code>pandas</code> and <code>openpyxl</code> (Excel). In <code>reports.py</code> check the line <code>from main.oracle import get_oracle_connection</code>.</p>\n<h3>How to add a report</h3>\n<p>Put a <code>.sql</code> file in <code>fast_search/sql/</code>. The first comment line is the title, the next comment lines the description. Every <code>:parameter</code> in the SQL becomes a field of the form by itself; the ones you do not use are simply not there. An optional parameter: <code>(:siteid is null or d.siteid = :siteid)</code>. Russian column names: <code>as "Сумма"</code>. Extra Python: a function with the file\'s name in <code>process.py</code>.</p>\n<pre><code class="language-sql">-- Сделки клиента\n-- Все сделки контрагента на дату архива.\nselect d.id as "ID сделки", d.amounteq / 100 as "Сумма"\nfrom   schema2.deal d\nwhere  d.contragentid = :contragentid\n  and  trunc(d.arcdate) = :arcdate\n</code></pre>\n<p>Sidebar link in base.html: <code>{% url \'fast-search\' %}</code>, icon <code>fa-solid fa-magnifying-glass-chart</code>.</p>\n<h3>Layout</h3>\n<pre><code class="language-plaintext">fast_search/\n    __init__.py\n    apps.py\n    urls.py\n    reports.py\n    process.py\n    views.py\n    templates/fast_search/style.html\n    templates/fast_search/index.html\n    templates/fast_search/report.html\n    sql/client_deals.sql\n    sql/deals_period.sql\n</code></pre>\n<h3>urls.py of the project</h3>\n<pre><code class="language-python">path("fast-search/", include("fast_search.urls")),\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-2. apps.py', 'category': 'programming', 'order': 2, 'summary': 'App config.', 'content': '<p>Step 2 of 11. Save as <code>fast_search/apps.py</code>.</p>\n<h3>apps.py</h3>\n<pre><code class="language-python">from django.apps import AppConfig\n\n\nclass FastSearchConfig(AppConfig):\n    default_auto_field = "django.db.models.BigAutoField"\n    name = "fast_search"\n    verbose_name = "Быстрый поиск"\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-3. urls.py', 'category': 'programming', 'order': 3, 'summary': 'Two pages: the list of reports and one report.', 'content': '<p>Step 3 of 11. Save as <code>fast_search/urls.py</code>.</p>\n<h3>urls.py</h3>\n<pre><code class="language-python">from django.urls import path\nfrom . import views\n\nurlpatterns = [\n    path("", views.index, name="fast-search"),\n    path("&lt;str:name&gt;/", views.report, name="fast-search-report"),\n]\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-4. reports.py', 'category': 'programming', 'order': 4, 'summary': 'The engine: reads the .sql files, finds the :parameters, makes the form, runs the query, shows the result. The usual parameters and their labels are in FIELDS at the top.', 'content': '<p>Step 4 of 11. Save as <code>fast_search/reports.py</code>.</p>\n<h3>reports.py</h3>\n<pre><code class="language-python">"""\nFAST SEARCH — a folder of .sql files is the whole app. Nothing is saved: the query runs,\nthe page shows the result, the Excel button downloads it.\n\nTO ADD A REPORT: put one file in fast_search/sql/, for example client_deals.sql:\n\n    -- Сделки клиента\n    -- Все сделки контрагента на дату архива.\n    select d.id         as "ID сделки",\n           d.amounteq   as "Сумма"\n    from   schema2.deal d\n    where  d.contragentid = :contragentid\n      and  trunc(d.arcdate) = :arcdate\n\nThat is all. Open /fast-search/ and it is there.\n  - the FIRST comment line is the title, the next comment lines are the description;\n  - the file name (client_deals) is the address: /fast-search/client_deals/;\n  - the form is made from the parameters in the SQL (:contragentid, :arcdate). A parameter\n    that is not in the SQL is not in the form, so there is nothing to switch on or off;\n  - column names: write them in Russian with double quotes (as "Сумма") and the page and\n    Excel show them like that.\n\nAN OPTIONAL PARAMETER (empty field = everything) is written like this:\n\n      and  (:siteid is null or d.siteid = :siteid)\n\nEXTRA PYTHON (optional): a function in process.py with the SAME NAME as the file gets the\ntable and the form values and returns the table to show. See process.py.\n"""\nimport re\nimport time\nfrom datetime import date\nfrom pathlib import Path\n\nimport pandas as pd\n\nfrom main.oracle import get_oracle_connection\n\nfrom . import process\n\nSQL_DIR = Path(__file__).resolve().parent / "sql"\n\n# The parameters you use often: name in the SQL → (label on the form, type).\n# type "date" = a calendar field; "text" = a text field (ids, codes ...).\n# A parameter that is not here still works: a text field (or a date if its name ends in "date").\nFIELDS = {\n    "pdate":        ("Дата", "date"),\n    "arcdate":      ("Дата архива", "date"),\n    "startdate":    ("Дата с", "date"),\n    "enddate":      ("Дата по", "date"),\n    "contragentid": ("ID контрагента", "text"),\n    "dealid":       ("ID сделки", "text"),\n    "siteid":       ("МФО (siteid)", "text"),\n}\n\nSHOW_ROWS = 500          # rows shown on the page; Excel always gets them all\nEXCEL_MAX_ROWS = 1_000_000   # Excel holds 1 048 576 rows: a bigger result is given as CSV\n\n\n# ═══════════════════════════════ THE REPORTS ═══════════════════════════════════════\n\ndef all_reports():\n    """Every .sql file in the folder, sorted by title."""\n    reports = [read_report(path.stem) for path in SQL_DIR.glob("*.sql")]\n    return sorted(reports, key=lambda r: r["title"].lower())\n\n\ndef read_report(name):\n    """One report by its file name, or None if there is no such file."""\n    path = SQL_DIR / f"{name}.sql"\n    if not name.replace("_", "").replace("-", "").isalnum() or not path.exists():\n        return None\n    text = path.read_text(encoding="utf-8")\n\n    comments = []\n    for line in text.splitlines():\n        line = line.strip()\n        if line.startswith("--"):\n            comments.append(line[2:].strip())\n        elif line:\n            break\n\n    params = find_params(text)\n    return {\n        "name": name,\n        "title": comments[0] if comments else name,\n        "description": " ".join(comments[1:]),\n        "sql": text.strip().rstrip(";"),       # SQL Developer\'s «;» at the end breaks oracledb\n        "params": params,\n        "fields": [field(p) for p in params],\n    }\n\n\ndef find_params(sql):\n    """The :names in the SQL, in the order of FIELDS first, then as they come.\n    Comments and \'text in quotes\' are skipped, so to_char(x, \'HH24:MI\') is not a parameter."""\n    clean = re.sub(r"/\\*.*?\\*/", " ", sql, flags=re.S)\n    clean = re.sub(r"--[^\\n]*", " ", clean)\n    clean = re.sub(r"\'[^\']*\'", " ", clean)\n    found = []\n    for name in re.findall(r"(?&lt;![:\\w]):([A-Za-z_]\\w*)", clean):\n        if name.lower() not in found:\n            found.append(name.lower())\n    known = [p for p in FIELDS if p in found]\n    return known + [p for p in found if p not in known]\n\n\ndef field(name):\n    """The form field of one parameter: name, label, type."""\n    label, kind = FIELDS.get(name, (name, "date" if name.endswith("date") else "text"))\n    return {"name": name, "label": label, "type": kind}\n\n\ndef read_values(report, data):\n    """The form values (request.GET) → {param: value} for Oracle, and a list of errors.\n    An empty field is None (NULL in the SQL)."""\n    values, errors = {}, []\n    for f in report["fields"]:\n        raw = data.get(f["name"], "").strip()\n        if not raw:\n            values[f["name"]] = None\n        elif f["type"] == "date":\n            try:\n                values[f["name"]] = date.fromisoformat(raw)\n            except ValueError:\n                errors.append(f"«{f[\'label\']}»: не дата ({raw})")\n        else:\n            values[f["name"]] = raw\n    return values, errors\n\n\n# ═══════════════════════════════ RUN ═══════════════════════════════════════════════\n\n# The last result, so the Excel button does not run the same query again.\n# Each gunicorn worker keeps its own one (in memory only, never on disk).\nMEMORY = {"key": None, "table": None, "seconds": None}\n\n\ndef get_table(report, values):\n    """The result of the report for these values: from MEMORY if it was just run, else from Oracle."""\n    key = (report["name"], report["sql"], tuple(sorted((k, str(v)) for k, v in values.items())))\n    if MEMORY["key"] != key:\n        started = time.time()\n        table = run(report["sql"], values)\n        extra = getattr(process, report["name"], None)\n        if extra is not None:\n            table = extra(table, values)\n        MEMORY.update(key=key, table=table, seconds=time.time() - started)\n    return MEMORY["table"], MEMORY["seconds"]\n\n\ndef run(sql, values):\n    """Run one query and return it as a pandas table."""\n    with get_oracle_connection() as conn:\n        cursor = conn.cursor()\n        cursor.arraysize = 5000                 # fetch in big packs: much faster on big results\n        cursor.execute(sql, values)\n        # Oracle gives unquoted names in CAPITALS: make them small. "Сумма" in quotes stays.\n        columns = [c[0].lower() if c[0].isascii() and c[0].isupper() else c[0] for c in cursor.description]\n        return pd.DataFrame(cursor.fetchall(), columns=columns)\n\n\n# ═══════════════════════════════ SHOW ══════════════════════════════════════════════\n\ndef show(value):\n    """One cell for the page: 1 234 567,89 · 31.12.2025 · empty for NULL."""\n    if value is None or (not isinstance(value, str) and pd.isna(value)):\n        return ""\n    if isinstance(value, bool):\n        return "да" if value else "нет"\n    if isinstance(value, (int, float)) or hasattr(value, "as_integer_ratio"):\n        if float(value).is_integer() and abs(value) &lt; 1e15:\n            return f"{int(value):,}".replace(",", "\xa0")\n        return f"{value:,.2f}".replace(",", "\xa0").replace(".", ",")\n    if hasattr(value, "strftime"):\n        if getattr(value, "hour", 0) or getattr(value, "minute", 0):\n            return value.strftime("%d.%m.%Y %H:%M")\n        return value.strftime("%d.%m.%Y")\n    return str(value)\n\n\ndef preview(table):\n    """The first SHOW_ROWS rows, ready for the template; numbers are right-aligned."""\n    head = table.head(SHOW_ROWS)\n    numeric = [pd.api.types.is_numeric_dtype(table[c]) and not pd.api.types.is_bool_dtype(table[c])\n               for c in table.columns]\n    return {\n        "columns": [{"name": str(c), "num": n} for c, n in zip(table.columns, numeric)],\n        "rows": [[{"v": show(v), "num": n} for v, n in zip(row, numeric)]\n                 for row in head.itertuples(index=False)],\n        "total": len(table),\n        "cut": len(table) &gt; SHOW_ROWS,\n    }\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-5. process.py', 'category': 'programming', 'order': 5, 'summary': 'Optional Python per report: a function with the same name as the .sql file.', 'content': '<p>Step 5 of 11. Save as <code>fast_search/process.py</code>.</p>\n<h3>process.py</h3>\n<pre><code class="language-python">"""\nOPTIONAL extra work on a report\'s result, in Python.\n\nMost reports need nothing here: the SQL does the job. When it does not (divide by 100,\nadd a column, merge two columns, sort ...), write a function with the SAME NAME as the\n.sql file. It gets:\n    table   — the pandas table Oracle returned\n    values  — the form values, e.g. {"startdate": date(2026, 1, 1), "siteid": "01234"}\nand returns the table to show and to put in Excel.\n\nNo function for a report = the table is shown as Oracle returned it.\n"""\n\n\ndef deals_period(table, values):\n    """Example for sql/deals_period.sql: amounts are in tiyin → сум, biggest first."""\n    if "Сумма" in table:\n        table["Сумма"] = table["Сумма"] / 100\n        table = table.sort_values("Сумма", ascending=False)\n    return table\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-6. views.py', 'category': 'programming', 'order': 6, 'summary': 'The views: the form (GET), the result, the Excel download.', 'content': '<p>Step 6 of 11. Save as <code>fast_search/views.py</code>.</p>\n<h3>views.py</h3>\n<pre><code class="language-python">"""\nThe pages of fast search. Two pages only:\n\n    /fast-search/                    every report (every .sql file in fast_search/sql/)\n    /fast-search/client_deals/       one report: its form, and after «Показать» the result\n\nThe form sends GET, so a result has its own address: send it to a colleague and they get\nthe same result. «Excel» is the same address with &amp;excel=1.\n"""\nfrom datetime import date\nfrom io import BytesIO\n\nfrom django.http import Http404, HttpResponse\nfrom django.shortcuts import render\n\nfrom . import reports\n\n\ndef index(request):\n    """Every report, as cards."""\n    return render(request, "fast_search/index.html", {"reports": reports.all_reports()})\n\n\ndef report(request, name):\n    """One report: the form; with ?run the result; with ?excel the result as a file."""\n    rep = reports.read_report(name)\n    if rep is None:\n        raise Http404("Нет такого отчёта")\n\n    fields = [dict(f, value=request.GET.get(f["name"], "")) for f in rep["fields"]]\n    context = {"report": rep, "fields": fields}\n    if "run" not in request.GET and "excel" not in request.GET:\n        return render(request, "fast_search/report.html", context)\n\n    values, errors = reports.read_values(rep, request.GET)\n    if errors:\n        context["errors"] = errors\n        return render(request, "fast_search/report.html", context)\n    try:\n        table, seconds = reports.get_table(rep, values)\n    except Exception as error:                  # an Oracle error: show it on the page\n        context["oracle_error"] = str(error)\n        return render(request, "fast_search/report.html", context)\n\n    if "excel" in request.GET:\n        return download(table, name)\n\n    query = request.GET.copy()\n    query.pop("excel", None)\n    context.update(reports.preview(table))\n    context.update({"ran": True, "seconds": f"{seconds:.1f}", "query": query.urlencode()})\n    return render(request, "fast_search/report.html", context)\n\n\ndef download(table, name):\n    """The whole result as .xlsx (or .csv when it is too big for Excel)."""\n    stamp = date.today().isoformat()\n    if len(table) &gt; reports.EXCEL_MAX_ROWS:\n        response = HttpResponse(content_type="text/csv; charset=utf-8")\n        response["Content-Disposition"] = f\'attachment; filename="{name}_{stamp}.csv"\'\n        response.write("\ufeff")                # so Excel opens the Russian letters right\n        table.to_csv(response, index=False, sep=";")\n        return response\n    buffer = BytesIO()\n    table.to_excel(buffer, index=False, sheet_name=name[:31])\n    response = HttpResponse(buffer.getvalue(),\n                            content_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet")\n    response["Content-Disposition"] = f\'attachment; filename="{name}_{stamp}.xlsx"\'\n    return response\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-7. templates/fast_search/style.html', 'category': 'programming', 'order': 7, 'summary': 'The look (Kapitalbank colours), shared by both pages.', 'content': '<p>Step 7 of 11. Save as <code>fast_search/templates/fast_search/style.html</code>.</p>\n<h3>templates/fast_search/style.html</h3>\n<pre><code class="language-html">{% comment %}\n  The look of fast search (Kapitalbank colours: yellow leads, charcoal second, red only for errors).\n  Everything sits under .fs so it never touches the rest of the site.\n{% endcomment %}\n&lt;style&gt;\n  .fs{--ink:#0B0B0C;--gold:#F2C230;--gd:#C9971A;--gtext:#8C6A12;--rule:#E4E1D8;--paper:#FAF8F2;--muted:#8A867C;--bad:#B3341F;color:var(--ink)}\n  .fs a{color:inherit}\n  .fs .hero{background:var(--ink);color:#fff;border-radius:12px;padding:20px 24px;margin-bottom:20px}\n  .fs .hero .eyebrow{font-size:11px;letter-spacing:.2em;text-transform:uppercase;color:var(--gold)}\n  .fs .hero h1{font-weight:500;font-size:24px;margin:6px 0 8px}\n  .fs .hero h1 i{color:var(--gold);margin-right:10px}\n  .fs .hero .sub{font-size:13px;color:#B9B5AB}\n  .fs .hero .sub a{color:#fff;text-decoration:none;border-bottom:1px dotted #777}\n  .fs .btn-go{background:var(--gold);border:none;color:var(--ink);font-weight:600}\n  .fs .btn-go:hover{background:var(--gd);color:var(--ink)}\n  .fs .box{background:#fff;border:1px solid var(--rule);border-radius:12px;margin-bottom:20px}\n  .fs .box-head{background:var(--paper);border-bottom:1px solid var(--rule);border-radius:12px 12px 0 0;\n       padding:10px 16px;font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:var(--gtext);\n       display:flex;justify-content:space-between;align-items:center;gap:8px;flex-wrap:wrap}\n  .fs .box-head i{margin-right:8px;color:var(--gd)}\n  .fs .box-head .hint{letter-spacing:0;text-transform:none;color:var(--muted);font-size:12px}\n  .fs .box-body{padding:16px}\n  .fs .card-r{display:block;text-decoration:none;background:#fff;border:1px solid var(--rule);border-radius:12px;\n       padding:16px 18px;height:100%;transition:border-color .15s, box-shadow .15s}\n  .fs .card-r:hover{border-color:var(--gold);box-shadow:0 4px 14px rgba(0,0,0,.07)}\n  .fs .card-r .t{font-size:17px;font-weight:600}\n  .fs .card-r .d{font-size:13px;color:var(--muted);margin-top:4px}\n  .fs .chip{display:inline-block;font-size:11.5px;background:var(--paper);border:1px solid var(--rule);\n       border-radius:20px;padding:1px 9px;margin:8px 4px 0 0;color:var(--gtext)}\n  .fs label{font-size:12px;color:var(--muted);margin-bottom:3px}\n  .fs .result{max-height:70vh;overflow:auto}\n  .fs .result table{font-size:13px;margin:0}\n  .fs .result th{position:sticky;top:0;background:var(--paper);white-space:nowrap;font-weight:600;\n       border-bottom:2px solid var(--gold)}\n  .fs .result td{white-space:nowrap}\n  .fs .m{text-align:right;font-variant-numeric:tabular-nums}\n  .fs .err{border-left:4px solid var(--bad)}\n  .fs pre.sql{background:var(--paper);border:1px solid var(--rule);border-radius:8px;padding:12px;font-size:12.5px;\n       white-space:pre-wrap;margin:0}\n  .fs details summary{cursor:pointer;color:var(--gtext);font-size:13px}\n  .fs .nothing{padding:16px;color:var(--muted)}\n  @media print{.no-print{display:none!important}.fs .result{max-height:none;overflow:visible}}\n&lt;/style&gt;\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-8. templates/fast_search/index.html', 'category': 'programming', 'order': 8, 'summary': 'Every report as a card.', 'content': '<p>Step 8 of 11. Save as <code>fast_search/templates/fast_search/index.html</code>.</p>\n<h3>templates/fast_search/index.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% comment %}\n  Every report: one card per .sql file in fast_search/sql/. The chips are the form fields.\n{% endcomment %}\n\n{% block extra_css %}{% include "fast_search/style.html" %}{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="fs container-fluid px-3 px-md-4 py-4"&gt;\n  &lt;div class="hero"&gt;\n    &lt;div class="eyebrow"&gt;Запрос → таблица → Excel&lt;/div&gt;\n    &lt;h1&gt;&lt;i class="fa-solid fa-magnifying-glass-chart"&gt;&lt;/i&gt;Быстрый поиск&lt;/h1&gt;\n    &lt;div class="sub"&gt;Ничего не сохраняется: запрос выполняется, когда вы нажимаете «Показать».&lt;/div&gt;\n  &lt;/div&gt;\n\n  {% if reports %}\n  &lt;div class="row g-3"&gt;\n    {% for r in reports %}\n    &lt;div class="col-12 col-md-6 col-xl-4"&gt;\n      &lt;a class="card-r" href="{% url \'fast-search-report\' r.name %}"&gt;\n        &lt;div class="t"&gt;{{ r.title }}&lt;/div&gt;\n        {% if r.description %}&lt;div class="d"&gt;{{ r.description }}&lt;/div&gt;{% endif %}\n        {% for f in r.fields %}&lt;span class="chip"&gt;{{ f.label }}&lt;/span&gt;{% empty %}&lt;span class="chip"&gt;без параметров&lt;/span&gt;{% endfor %}\n      &lt;/a&gt;\n    &lt;/div&gt;\n    {% endfor %}\n  &lt;/div&gt;\n  {% else %}\n  &lt;div class="alert alert-light border"&gt;Отчётов пока нет. Положите файл &lt;code&gt;.sql&lt;/code&gt; в папку &lt;code&gt;fast_search/sql/&lt;/code&gt;.&lt;/div&gt;\n  {% endif %}\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-9. templates/fast_search/report.html', 'category': 'programming', 'order': 9, 'summary': 'One report: the form, the result table, Excel, the SQL.', 'content': '<p>Step 9 of 11. Save as <code>fast_search/templates/fast_search/report.html</code>.</p>\n<h3>templates/fast_search/report.html</h3>\n<pre><code class="language-html">{% extends "base.html" %}\n{% comment %}\n  One report: the form made from the :parameters of its SQL, then the result.\n  GET form, so every result has its own address; «Excel» = the same address + &amp;excel=1. No JavaScript.\n{% endcomment %}\n\n{% block extra_css %}{% include "fast_search/style.html" %}{% endblock extra_css %}\n\n{% block content %}\n&lt;div class="fs container-fluid px-3 px-md-4 py-4"&gt;\n  &lt;div class="hero"&gt;\n    &lt;div class="eyebrow"&gt;Быстрый поиск&lt;/div&gt;\n    &lt;h1&gt;&lt;i class="fa-solid fa-table"&gt;&lt;/i&gt;{{ report.title }}&lt;/h1&gt;\n    &lt;div class="sub"&gt;&lt;a class="no-print" href="{% url \'fast-search\' %}"&gt;&lt;i class="fa-solid fa-arrow-left me-1"&gt;&lt;/i&gt;Все отчёты&lt;/a&gt;\n      {% if report.description %}&lt;span class="mx-2" style="color:#F2C230"&gt;·&lt;/span&gt;{{ report.description }}{% endif %}&lt;/div&gt;\n  &lt;/div&gt;\n\n  &lt;form method="get" class="box no-print"&gt;\n    &lt;div class="box-head"&gt;&lt;span&gt;&lt;i class="fa-solid fa-sliders"&gt;&lt;/i&gt;Параметры&lt;/span&gt;\n      &lt;span class="hint"&gt;пустое поле = NULL в запросе&lt;/span&gt;&lt;/div&gt;\n    &lt;div class="box-body"&gt;\n      &lt;div class="row g-3 align-items-end"&gt;\n        {% for f in fields %}\n        &lt;div class="col-6 col-md-4 col-xl-2"&gt;\n          &lt;label for="f-{{ f.name }}" class="form-label"&gt;{{ f.label }}&lt;/label&gt;\n          &lt;input id="f-{{ f.name }}" name="{{ f.name }}" value="{{ f.value }}" class="form-control form-control-sm"\n                 type="{% if f.type == \'date\' %}date{% else %}text{% endif %}"&gt;\n        &lt;/div&gt;\n        {% endfor %}\n        &lt;div class="col-12 col-md-auto"&gt;\n          &lt;button class="btn btn-go btn-sm px-4" type="submit" name="run" value="1"&gt;&lt;i class="fa-solid fa-play me-1"&gt;&lt;/i&gt;Показать&lt;/button&gt;\n        &lt;/div&gt;\n      &lt;/div&gt;\n    &lt;/div&gt;\n  &lt;/form&gt;\n\n  {% if errors %}\n  &lt;div class="alert alert-warning err"&gt;{% for e in errors %}&lt;div&gt;{{ e }}&lt;/div&gt;{% endfor %}&lt;/div&gt;\n  {% endif %}\n\n  {% if oracle_error %}\n  &lt;div class="alert alert-danger err"&gt;\n    &lt;strong&gt;&lt;i class="fa-solid fa-triangle-exclamation me-2"&gt;&lt;/i&gt;Запрос вернул ошибку&lt;/strong&gt;\n    &lt;pre class="sql mt-2"&gt;{{ oracle_error }}&lt;/pre&gt;\n  &lt;/div&gt;\n  {% endif %}\n\n  {% if ran %}\n  &lt;div class="box"&gt;\n    &lt;div class="box-head"&gt;\n      &lt;span&gt;&lt;i class="fa-solid fa-table-list"&gt;&lt;/i&gt;Результат&lt;/span&gt;\n      &lt;span class="d-flex align-items-center gap-2"&gt;\n        &lt;span class="hint"&gt;{{ total }} строк · {{ seconds }} с{% if cut %} · показаны первые {{ rows|length }}, в Excel — все{% endif %}&lt;/span&gt;\n        {% if total %}\n        &lt;a class="btn btn-go btn-sm no-print" href="?{{ query }}&amp;excel=1"&gt;&lt;i class="fa-solid fa-file-excel me-1"&gt;&lt;/i&gt;Excel&lt;/a&gt;\n        &lt;button class="btn btn-outline-secondary btn-sm no-print" type="button" onclick="window.print()"&gt;&lt;i class="fa-solid fa-print"&gt;&lt;/i&gt;&lt;/button&gt;\n        {% endif %}\n      &lt;/span&gt;\n    &lt;/div&gt;\n    {% if rows %}\n    &lt;div class="result"&gt;\n      &lt;table class="table table-sm table-hover align-middle"&gt;\n        &lt;thead&gt;&lt;tr&gt;{% for c in columns %}&lt;th{% if c.num %} class="m"{% endif %}&gt;{{ c.name }}&lt;/th&gt;{% endfor %}&lt;/tr&gt;&lt;/thead&gt;\n        &lt;tbody&gt;\n        {% for row in rows %}\n          &lt;tr&gt;{% for cell in row %}&lt;td{% if cell.num %} class="m"{% endif %}&gt;{{ cell.v }}&lt;/td&gt;{% endfor %}&lt;/tr&gt;\n        {% endfor %}\n        &lt;/tbody&gt;\n      &lt;/table&gt;\n    &lt;/div&gt;\n    {% else %}\n    &lt;div class="nothing"&gt;&lt;i class="fa-solid fa-circle-info me-1"&gt;&lt;/i&gt;Ничего не найдено.&lt;/div&gt;\n    {% endif %}\n  &lt;/div&gt;\n  {% endif %}\n\n  &lt;details class="no-print"&gt;\n    &lt;summary&gt;&lt;i class="fa-solid fa-code me-1"&gt;&lt;/i&gt;SQL этого отчёта — &lt;code&gt;fast_search/sql/{{ report.name }}.sql&lt;/code&gt;&lt;/summary&gt;\n    &lt;pre class="sql mt-2"&gt;{{ report.sql }}&lt;/pre&gt;\n  &lt;/details&gt;\n&lt;/div&gt;\n{% endblock content %}\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-10. sql/client_deals.sql', 'category': 'programming', 'order': 10, 'summary': "Example report: a client's deals on an archive date, branch optional.", 'content': '<p>Step 10 of 11. Save as <code>fast_search/sql/client_deals.sql</code>.</p>\n<h3>sql/client_deals.sql</h3>\n<pre><code class="language-sql">-- Сделки клиента\n-- Все сделки контрагента на дату архива. МФО можно оставить пустым — тогда по всем филиалам.\nselect d.id            as "ID сделки",\n       d.siteid        as "МФО",\n       d.dealtypeid    as "Тип",\n       d.currencyid    as "Валюта",\n       d.amounteq / 100 as "Сумма, сум",\n       d.closedate     as "Дата закрытия"\nfrom   schema2.deal d\nwhere  d.contragentid = :contragentid\n  and  trunc(d.arcdate) = :arcdate\n  and  (:siteid is null or d.siteid = :siteid)\norder by d.id\n</code></pre>\n'})

TUTORIALS.append({'title': 'FS-11. sql/deals_period.sql', 'category': 'programming', 'order': 11, 'summary': 'Example report: deals opened between two dates, with extra Python in process.py.', 'content': '<p>Step 11 of 11. Save as <code>fast_search/sql/deals_period.sql</code>.</p>\n<h3>sql/deals_period.sql</h3>\n<pre><code class="language-sql">-- Сделки за период\n-- Сделки, открытые между двумя датами. Пример с обработкой в process.py (тийины → сумы).\nselect d.id            as "ID сделки",\n       d.siteid        as "МФО",\n       d.contragentid  as "ID контрагента",\n       d.amounteq      as "Сумма",\n       d.opendate      as "Дата открытия"\nfrom   schema2.deal d\nwhere  d.opendate between :startdate and :enddate\n  and  (:siteid is null or d.siteid = :siteid)\n</code></pre>\n'})
